// Anti-doublon : une commande deja ouverte dans Todoist (raccourci Climapro, fil, saisie a la main) n'est pas recreee.
// Meme article = au moins 60 % des mots du plus court en commun (ex. "Colson" et "Colson noirs 300 mm").
const VIDES = ['commander', 'commande', 'acheter', 'prendre', 'des', 'les', 'une', 'pour', 'avec', 'plus', 'modele', 'grand', 'petit', 'gros'];
const mots = s => [...new Set(String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/^a commander : /, '').replace(/[^a-z0-9]+/g, ' ').split(' ').filter(w => w.length > 2 && !VIDES.includes(w)).map(w => w.replace(/s$/, '')))];
const pareil = (a, b) => { if (!a.length || !b.length) return false; const n = a.filter(w => b.includes(w)).length; return n >= 1 && n / Math.min(a.length, b.length) >= 0.6; };
const ouvertes = ((($input.first() || {}).json || {}).results || []).map(t => mots(t.content));
const deja = ouvertes.slice();
const out = [];
for (const it of $('Extraire commandes').all()) {
  const c = it.json;
  const m = mots(c.article);
  if (deja.some(o => pareil(m, o))) continue;
  deja.push(m);
  out.push({ json: { todoist: {
    content: 'À commander : ' + c.article + (c.client ? ' - ' + c.client : ''),
    description: 'Demandé par ' + c.auteur + ' dans le fil équipe' + (c.quand ? ' le ' + c.quand : '') + '.\nMessage : ' + c.textes,
    labels: ['commande', 'memo'],
    project_id: '6hh423vw4vGgHFPw',
    section_id: '6hjM3Rw4RPRw474w',
    priority: 1
  } } });
}
return out;

// Une note par client, avec les messages d'origine et les liens des photos.
const lignes = $('Lignes du lot').all().map(i => i.json);
if (!lignes.length || !lignes[0].traite) return [];
let t = '';
try { t = ($('Analyser (Haiku)').first().json.content || []).map(c => c.text || '').join('').trim(); } catch (e) {}
let o = null;
try { const a = t.indexOf('{'), b = t.lastIndexOf('}'); o = JSON.parse(t.slice(a, b + 1)); } catch (e) { o = null; }
let notes = (o && Array.isArray(o.notes)) ? o.notes : [];
if (lignes[0].illisible) notes = [{ message_ids: lignes.map(l => l.id), rattachement: 'aucun', client_nom: '', client_id: '', resume: '- Lot non analyse (reponse illisible deux fois) : a trier a la main.' }];
const rows = {};
for (const it of $('Lire non traites').all()) rows[it.json.id] = it.json;
const NL = String.fromCharCode(10);
const out = [];
for (const n of notes) {
  const mids = (n.message_ids || []).map(Number).filter(id => rows[id]);
  if (!mids.length) continue;
  const msgs = mids.map(id => {
    const r = rows[id];
    const d = DateTime.fromISO(String(r.date || r.createdAt), { zone: 'utc' }).setZone('Europe/Paris');
    let l = (d.isValid ? d.toFormat('dd/MM HH:mm') : '') + ' ' + (r.auteur || '?') + ' : ' + (r.texte || (r.photo_drive_id ? '(photo)' : ''));
    if (r.photo_drive_id) l += NL + 'Photo : https://drive.google.com/file/d/' + r.photo_drive_id + '/view';
    return l;
  });
  const premier = rows[mids[0]];
  const d0 = DateTime.fromISO(String(premier.date || premier.createdAt), { zone: 'utc' }).setZone('Europe/Paris');
  const resume = String(n.resume || '').replace(/[–—]/g, '-').trim();
  const idIndice = /^\d{3,12}$/.test(String(n.client_id || '')) ? String(n.client_id) : '';
  let ratt = String(n.rattachement || '');
  if (!['nomme', 'planning', 'aucun'].includes(ratt)) ratt = idIndice ? 'planning' : (n.client_nom ? 'nomme' : 'aucun');
  const contenu = 'Fil equipe Telegram du ' + (d0.isValid ? d0.toFormat('dd/MM/yyyy') : '') + ' (' + [...new Set(mids.map(id => rows[id].auteur || '?'))].join(', ') + ')' + NL
    + 'Resume :' + NL + resume + NL + NL + '[Messages]' + NL + msgs.join(NL);
  out.push({ json: { message_ids: mids, rattachement: ratt, client_nom: String(n.client_nom || '').trim(), client_id_indice: idIndice, date_lot: d0.isValid ? d0.toFormat('dd/MM/yyyy') : '', contenu } });
}
return out;

// Demandes de materiel reperees par Haiku dans le lot (champ commandes). Rien si le lot n'est pas encore traite.
const lignes = $input.all().map(i => i.json);
if (!lignes.length || !lignes[0].traite || lignes[0].illisible) return [];
let t = '';
try { t = ($('Analyser (Haiku)').first().json.content || []).map(c => c.text || '').join('').trim(); } catch (e) {}
let o = null;
try { const a = t.indexOf('{'), b = t.lastIndexOf('}'); o = JSON.parse(t.slice(a, b + 1)); } catch (e) { o = null; }
const cmds = (o && Array.isArray(o.commandes)) ? o.commandes : [];
const rows = {};
for (const it of $('Lire non traites').all()) rows[it.json.id] = it.json;
const out = [];
for (const c of cmds) {
  const mids = (c.message_ids || []).map(Number).filter(id => rows[id]);
  const article = String(c.article || '').replace(/[–—]/g, '-').replace(/\s+/g, ' ').trim().slice(0, 120);
  if (!mids.length || !article) continue;
  const r = rows[mids[0]];
  const d = DateTime.fromISO(String(r.date || r.createdAt), { zone: 'utc' }).setZone('Europe/Paris');
  out.push({ json: {
    article,
    client: String(c.client_nom || '').trim().slice(0, 80),
    auteur: [...new Set(mids.map(id => rows[id].auteur || '?'))].join(', '),
    quand: d.isValid ? d.toFormat("dd/MM/yyyy 'à' HH'h'mm") : '',
    textes: mids.map(id => rows[id].texte || '').filter(Boolean).join(' / ').slice(0, 600)
  } });
}
return out;

// Lecture de la reponse de Haiku.
// Reponse illisible : 1er echec -> le lot sera retente au passage suivant ; 2e echec -> lot classe et envoye a Laurent pour tri manuel.
let t = '';
try { t = ($input.first().json.content || []).map(c => c.text || '').join('').trim(); } catch (e) {}
let o = null;
try { const a = t.indexOf('{'), b = t.lastIndexOf('}'); o = JSON.parse(t.slice(a, b + 1)); } catch (e) { o = null; }
const ids = $('Preparer lot').first().json.ids || [];
const rows = {};
for (const it of $('Lire non traites').all()) rows[it.json.id] = it.json;
const ess = id => Number((rows[id] || {}).essais) || 0;
if (!o || !Array.isArray(o.notes)) {
  const essais = Math.max(0, ...ids.map(ess)) + 1;
  const fini = essais >= 2;
  return ids.map(id => ({ json: { id, traite: fini, essais, illisible: true, client_nom: fini ? '(lot illisible)' : '' } }));
}
const nomPar = {};
for (const n of o.notes) for (const id of (n.message_ids || [])) nomPar[Number(id)] = String(n.client_nom || '').trim().slice(0, 120);
return ids.map(id => ({ json: { id, traite: true, essais: ess(id), illisible: false, client_nom: nomPar[id] || '' } }));

// Messages effectivement consignes dans Interfast : on le note dans la table.
const src = $('Note autorisee ?').all();
const out = [];
$input.all().forEach((it, i) => {
  const n = (src[i] || {}).json || {};
  for (const id of (n.message_ids || [])) out.push({ json: { id, client_id: Number(n.client_id) || null, client_nom: n.client_nom || '' } });
});
return out;

// Interventions du jour (tous techniciens) pour aider a rattacher un message au bon client.
const r = $input.first().json || {};
const items = (r.ok && r.data && Array.isArray(r.data.items)) ? r.data.items : [];
const lignes = items.map(ev => {
  const c = ev.client || {};
  const a = ev.address || c.address || {};
  const techs = (ev.users || []).map(u => u.firstName || u.name || u.id).join(', ');
  return '- ' + (ev.heureParis || '') + ' ' + String(c.name || ev.clientName || '?').trim() + ' (client_id ' + (c.id || ev.clientId || '?') + ') ' + (a.city || '') + ' ; ' + String(ev.title || ev.name || ev.type || '').replace(/<[^>]+>/g, ' ').slice(0, 120) + ' ; techniciens : ' + techs;
});
return [{ json: { planning: lignes.join('\n').slice(0, 6000) || '(aucune intervention trouvee aujourd hui)' } }];

// Message prive a Laurent pour une note a valider : resume visible, messages d'origine repliables.
const r = $input.item.json || {};
const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const motif = r.client_id ? (r.rattachement === 'planning' ? 'client devine par le planning' : 'client nomme, fiche trouvee') : (r.client_nom ? 'fiche introuvable ou en double' : 'client non identifie');
const parts = String(r.contenu || '').split('
[Messages]
');
const tete = parts[0].replace(/^Fil equipe Telegram du [^
]*
/, '').replace(/^Resume :
/, '');
const msgs = parts[1] || '';
let t = '<b>📝 ' + (r.client_nom ? esc(r.client_nom) : 'Client ?') + '</b>' + (r.client_id ? ' (id ' + esc(r.client_id) + ')' : '') + '
<i>' + motif + ' · ' + esc(r.date_lot || '') + '</i>

';
t += esc(tete.slice(0, 1500));
if (msgs) t += '

<blockquote expandable>' + esc(msgs.slice(0, 1800)) + '</blockquote>';
if (r.candidats) t += '
<b>Fiches possibles :</b>
' + esc(String(r.candidats).slice(0, 500));
t += '

<i>' + (r.client_id ? 'Autre client ? Reponds avec son nom ou son id.' : 'Reponds avec le nom du client ou son id.') + '</i>';
return { json: { id: r.id, texte: t, avec_client: !!r.client_id, bouton_ok: ('✅ ' + (r.client_nom || 'Valider')).slice(0, 40) } };

// Lot de messages du groupe pas encore traites. On attend 3 min de calme pour garder une rafale (photo + texte) ensemble.
const NOW = Date.now();
const rows = $input.all().map(i => i.json).filter(r => r && r.id);
if (!rows.length) return [];
const t = r => new Date(r.createdAt || r.date).getTime();
const plusRecent = Math.max(...rows.map(t));
if (NOW - plusRecent < 3 * 60 * 1000) return [];
const lot = rows.sort((a, b) => a.id - b.id).slice(0, 60);
const lignes = lot.map(r => {
  const d = DateTime.fromISO(String(r.date || r.createdAt), { zone: 'utc' }).setZone('Europe/Paris');
  const extra = (r.photo_drive_id ? ' (photo jointe)' : '') + (r.type && !['texte', 'photo'].includes(r.type) ? ' (' + r.type + ')' : '');
  return '[' + r.id + '] ' + (d.isValid ? d.toFormat('dd/MM/yyyy HH:mm') : '') + ' ' + (r.auteur || '?') + ' : ' + (r.texte || '') + extra;
});
const jour = DateTime.now().setZone('Europe/Paris').toISODate();
return [{ json: { ids: lot.map(r => r.id), texte: lignes.join('\n'), jour } }];

// Production : toutes les fiches clients sont possibles, mais TOUT_VALIDER = true => chaque note passe par Laurent (boutons Telegram).
// Pour laisser partir directement les notes sures (client nomme + fiche unique) : TOUT_VALIDER = false.
const TOUT_VALIDER = true;
const VIDES = ['client', 'clients', 'cliente', 'chez', 'monsieur', 'madame', 'mr', 'mme', 'la', 'le', 'les', 'de', 'du', 'des', 'et', 'sarl', 'sas', 'sci', 'societe', 'famille', 'villa', 'residence'];
const n = $('Eclater notes').item.json;
const res = $input.item.json || {};
const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const mots = norm(n.client_nom).split(' ').filter(w => w.length > 1 && !VIDES.includes(w));
const tous = (Array.isArray(res.items) ? res.items : []).filter(c => String(c.reference || '').toUpperCase().startsWith('C') && String(c.category || 'client') !== 'supplier');
const items = mots.length ? tous.filter(c => mots.every(w => norm(c.name).split(' ').some(m => m === w || (w.length >= 4 && m.startsWith(w))))) : [];
let id = n.client_id_indice;
let nom = n.client_nom;
if (!id && items.length === 1) { id = String(items[0].id); nom = String(items[0].name || '').trim(); }
let voie = (n.rattachement === 'nomme' && id) ? 'direct' : 'a_valider';
if (TOUT_VALIDER) voie = 'a_valider';
const liste = (items.length > 1 ? items : (items.length ? [] : tous)).slice(0, 5);
const candidats = liste.map(c => '- ' + String(c.name || '').trim() + ' (' + c.reference + ') : id ' + c.id).join('\n');
return { json: { ...n, client_id: id || '', client_nom: nom || '', voie, autorise: voie === 'direct', candidats } };
